 93	function manifestPath(uploadId: string): string {
 94		return join(ingestDir(), `${uploadId}.json`);
 95	}
 96	
 97	function sqlString(value: string): string {
 98		return `'${value.replace(/'/g, "''")}'`;
 99	}
100	
101	function quoteIdentifier(value: string): string {
102		return `"${value.replace(/"/g, '""')}"`;
103	}
104	
105	function toJsonSafe(value: unknown): unknown {
106		if (typeof value === 'bigint') return Number(value);
107		if (Array.isArray(value)) return value.map(toJsonSafe);
108		if (value && typeof value === 'object') {
109			return Object.fromEntries(
110				Object.entries(value).map(([key, nestedValue]) => [key, toJsonSafe(nestedValue)])
111			);
112		}
113		return value;
114	}
115	
116	function toNumber(value: unknown): number {
117		if (typeof value === 'bigint') return Number(value);
118		if (typeof value === 'number') return value;
119		if (typeof value === 'string') return Number(value);
120		return 0;
121	}
