124		if (!/^[0-9a-f-]{36}$/.test(uploadId)) return null;
125		const path = manifestPath(uploadId);
126		if (!existsSync(path)) return null;
127		return JSON.parse(await readFile(path, 'utf8')) as StoredUploadManifest;
128	}
