208			return {
209				valid: false,
210				errors: [`Indicator ${indicatorCode} does not exist`],
211				rowCount,
212				preview,
213				columns
214			};
215		}
216	
217		const indicatorId = indicatorRows[0].id;
218		if (!(await indicatorFrequencyExists(indicatorId, freq))) {
219			return {
220				valid: false,
221				errors: [`Indicator frequency ${indicatorCode}/${freq} is not defined`],
222				rowCount,
223				preview,
224				columns,
225				indicatorId
226			};
227		}
228	
229		const registeredDimensionColumns = await getRegisteredDimensionColumns(indicatorId, freq);
230	
231		try {
232			columns = await getParquetColumns(filePath);
233			rowCount = await countRows(filePath);
234			preview = await getPreview(filePath);
235		} catch (error) {
236			return {
237				valid: false,
238				errors: [
239					`Could not read uploaded file as Parquet: ${error instanceof Error ? error.message : 'unknown error'}`
240				],
241				rowCount,
242				preview,
243				columns,
244				indicatorId
245			};
246		}
247	
248		const columnMap = new Map<string, string>();
249		for (const column of columns) {
250			const normalized = column.toLowerCase();
251			if (columnMap.has(normalized)) {
252				errors.push(`Duplicate column after case normalization: ${column}`);
253			}
254			columnMap.set(normalized, column);
255	
256			if (column !== normalized) {
257				errors.push(
258					`Column ${column} must be named ${normalized}; upload columns are case-sensitive`
259				);
260			}
261		}
262	
263		const allowedColumns = new Set([
264			...REQUIRED_COLUMNS,
265			...OPTIONAL_CANONICAL_COLUMNS.filter(
266				(column) => registeredDimensionColumns.includes(column) || column.startsWith('ext_')
267			),
268			'obs_status'
269		]);
270	
271		for (const requiredColumn of REQUIRED_COLUMNS) {
272			if (!columnMap.has(requiredColumn)) errors.push(`Missing required column: ${requiredColumn}`);
273		}
274	
275		for (const column of columns.map((value) => value.toLowerCase())) {
276			if (!allowedColumns.has(column)) {
277				errors.push(
278					`Column ${column} is not allowed for ${indicatorCode}/${freq}; register it in indicator_dimensions first`
279				);
280			}
281		}
282	
283		if (rowCount === 0) errors.push('Uploaded file contains no rows');
284	
285		const hasRequiredColumns = REQUIRED_COLUMNS.every((column) => columnMap.has(column));
286		if (hasRequiredColumns) {
287			const indicatorColumn = quoteIdentifier(columnMap.get('indicator_code')!);
288			const freqColumn = quoteIdentifier(columnMap.get('freq')!);
289			const refAreaColumn = quoteIdentifier(columnMap.get('ref_area')!);
290			const obsValueColumn = quoteIdentifier(columnMap.get('obs_value')!);
291			const timeColumn = quoteIdentifier(columnMap.get('time_period')!);
292	
293			const mismatchedIndicatorCount = await countRows(
294				filePath,
295				`CAST(${indicatorColumn} AS VARCHAR) IS NULL OR CAST(${indicatorColumn} AS VARCHAR) <> ?`,
296				indicatorCode
297			);
298			if (mismatchedIndicatorCount > 0) {
299				errors.push(
300					`${mismatchedIndicatorCount} row(s) have indicator_code different from ${indicatorCode}`
301				);
302			}
303	
304			const mismatchedFreqCount = await countRows(
305				filePath,
306				`CAST(${freqColumn} AS VARCHAR) IS NULL OR CAST(${freqColumn} AS VARCHAR) <> ?`,
307				freq
308			);
309			if (mismatchedFreqCount > 0) {
310				errors.push(`${mismatchedFreqCount} row(s) have freq different from ${freq}`);
311			}
312	
313			const missingRefAreaCount = await countRows(filePath, `${refAreaColumn} IS NULL`);
314			if (missingRefAreaCount > 0) {
315				errors.push(`${missingRefAreaCount} row(s) have null ref_area`);
316			}
317	
318			const missingTimeCount = await countRows(filePath, `${timeColumn} IS NULL`);
319			if (missingTimeCount > 0) {
320				errors.push(`${missingTimeCount} row(s) have null time_period`);
321			}
322	
323			const invalidNumericCount = await countRows(
324				filePath,
325				`${obsValueColumn} IS NOT NULL AND TRY_CAST(${obsValueColumn} AS DOUBLE) IS NULL`
326			);
327			if (invalidNumericCount > 0) {
328				errors.push(
329					`${invalidNumericCount} row(s) have obs_value values that cannot be cast to DOUBLE`
330				);
331			}
332	
333			const timeRegexByFreq: Record<string, string> = {
334				A: '^[0-9]{4}$',
335				M: '^[0-9]{4}-(0[1-9]|1[0-2])$'
336			};
337			const timeRegex = timeRegexByFreq[freq];
338			if (timeRegex) {
339				const invalidTimeCount = await countRows(
340					filePath,
341					`CAST(${timeColumn} AS VARCHAR) IS NULL OR NOT regexp_full_match(CAST(${timeColumn} AS VARCHAR), ?)`,
342					timeRegex
343				);
344				if (invalidTimeCount > 0) {
345					errors.push(`${invalidTimeCount} row(s) have invalid time_period format for freq ${freq}`);
346				}
347			}
348		}
349	
350		return {
351			valid: errors.length === 0,
352			errors,
353			rowCount,
354			preview,
355			columns,
356			indicatorId
357		};
358	}
