360	export async function uploadIndicatorData(params: {
361		file: File;
362		indicatorCode: string;
363		freq: string;
364	}): Promise<UploadIndicatorDataResult> {
365		await mkdir(ingestDir(), { recursive: true });
366	
367		const uploadId = randomUUID();
368		const filePath = uploadFilePath(uploadId);
369		const buffer = Buffer.from(await params.file.arrayBuffer());
370		const checksum = createHash('sha256').update(buffer).digest('hex');
371	
372		await writeFile(filePath, buffer);
373	
374		const indicatorCode = params.indicatorCode.trim();
375		const freq = params.freq.trim().toUpperCase();
376		const validation = await validateUploadFile(filePath, indicatorCode, freq);
377		const { indicatorId: _indicatorId, ...publicValidation } = validation;
378	
379		if (!validation.valid) {
380			await unlink(filePath).catch(() => undefined);
381			return publicValidation;
382		}
383	
384		const manifest: StoredUploadManifest = {
385			uploadId,
386			indicatorCode,
387			freq,
388			filePath,
389			originalName: basename(params.file.name || 'upload.parquet'),
390			checksum,
391			rowCount: validation.rowCount,
392			columns: validation.columns,
393			createdAt: new Date().toISOString(),
394			status: 'uploaded'
395		};
396	
397		await writeManifest(manifest);
398	
399		return {
400			...publicValidation,
401			uploadId,
402			checksum
403		};
404	}
405	
406	function buildInsertSelect(manifest: StoredUploadManifest): string {
407		const availableColumns = new Set(manifest.columns.map((column) => column.toLowerCase()));
408		const selectExpressions = OBSERVATION_COLUMNS.map((column) => {
409			if (column === 'obs_value') {
410				return availableColumns.has(column)
411					? `TRY_CAST(${quoteIdentifier(column)} AS DOUBLE) AS ${quoteIdentifier(column)}`
412					: `NULL AS ${quoteIdentifier(column)}`;
413			}
414	
415			if (column === 'obs_status') {
416				return availableColumns.has(column)
417					? `COALESCE(CAST(${quoteIdentifier(column)} AS VARCHAR), 'A') AS ${quoteIdentifier(column)}`
418					: `'A' AS ${quoteIdentifier(column)}`;
419			}
420	
421			return availableColumns.has(column)
422				? `CAST(${quoteIdentifier(column)} AS VARCHAR) AS ${quoteIdentifier(column)}`
423				: `NULL AS ${quoteIdentifier(column)}`;
424		});
425	
426		return `
427			INSERT INTO observations (${OBSERVATION_COLUMNS.map(quoteIdentifier).join(', ')})
428			SELECT ${selectExpressions.join(', ')}
429			FROM read_parquet(${sqlString(manifest.filePath)})
430		`;
431	}
432	
433	async function publishUploadNow(uploadId: string): Promise<PublishUploadResult> {
434		const manifest = await readManifest(uploadId);
435		if (!manifest) throw new Error(`Upload ${uploadId} not found`);
436		if (manifest.status === 'published')
437			throw new Error(`Upload ${uploadId} has already been published`);
438		if (!existsSync(manifest.filePath)) throw new Error(`Uploaded file for ${uploadId} is missing`);
439	
440		const validation = await validateUploadFile(
441			manifest.filePath,
442			manifest.indicatorCode,
443			manifest.freq
444		);
445		if (!validation.valid || !validation.indicatorId) {
446			const error = new Error('Upload is no longer valid');
447			(error as Error & { details?: string[] }).details = validation.errors;
448			throw error;
449		}
450	
451		await runCanonicalQuery('BEGIN TRANSACTION');
452		try {
453			await runCanonicalQuery(
454				'DELETE FROM observations WHERE indicator_code = ? AND freq = ?',
455				manifest.indicatorCode,
456				manifest.freq
457			);
458			await runCanonicalQuery(buildInsertSelect(manifest));
459			await runCanonicalQuery('COMMIT');
460		} catch (error) {
461			await runCanonicalQuery('ROLLBACK').catch(() => undefined);
462			throw error;
463		}
464	
465		const rows = await runCanonicalQuery<{
466			rows_inserted: unknown;
467			period_start: string | null;
468			period_end: string | null;
469		}>(
470			`
471				SELECT
472					COUNT(*) AS rows_inserted,
473					MIN(time_period) AS period_start,
474					MAX(time_period) AS period_end
475				FROM observations
476				WHERE indicator_code = ? AND freq = ?
477			`,
478			manifest.indicatorCode,
479			manifest.freq
480		);
481		const rowsInserted = toNumber(rows[0]?.rows_inserted);
482	
483		const sourceRows = await runCanonicalQuery<{
484			ref_area: string;
485			row_count: unknown;
486			year_min: number | null;
487			year_max: number | null;
488		}>(
489			`
490				SELECT
491					ref_area,
492					COUNT(*) AS row_count,
493					MIN(TRY_CAST(SUBSTR(time_period, 1, 4) AS INTEGER)) AS year_min,
494					MAX(TRY_CAST(SUBSTR(time_period, 1, 4) AS INTEGER)) AS year_max
495				FROM observations
496				WHERE indicator_code = ? AND freq = ?
497				GROUP BY ref_area
498			`,
499			manifest.indicatorCode,
500			manifest.freq
501		);
502	
503		const db = getDb();
504		const release = await db.transaction(async (tx) => {
505			const [createdRelease] = await tx
506				.insert(dataReleases)
507				.values({
508					indicatorId: validation.indicatorId!,
509					periodStart: rows[0]?.period_start || null,
510					periodEnd: rows[0]?.period_end || null,
511					rowCount: rowsInserted,
512					sourceFormat: 'parquet',
513					sourceName: manifest.originalName,
514					status: 'published',
515					checksum: manifest.checksum
516				})
517				.returning({ id: dataReleases.id });
518	
519			await tx
520				.delete(indicatorDataSources)
521				.where(
522					and(
523						eq(indicatorDataSources.indicatorId, validation.indicatorId!),
524						eq(indicatorDataSources.freq, manifest.freq)
525					)
526				);
527	
528			if (sourceRows.length > 0) {
529				await tx.insert(indicatorDataSources).values(
530					sourceRows.map((row) => ({
531						indicatorId: validation.indicatorId!,
532						refArea: row.ref_area,
533						freq: manifest.freq,
534						yearMin: row.year_min,
535						yearMax: row.year_max,
536						rowCount: toNumber(row.row_count),
537						releaseId: createdRelease.id
538					}))
539				);
540			}
541	
542			return createdRelease;
543		});
544	
545		manifest.status = 'published';
546		manifest.releaseId = release.id;
547		manifest.publishedAt = new Date().toISOString();
548		await writeManifest(manifest);
549	
550		return {
551			releaseId: release.id,
552			rowsInserted,
553			indicatorCode: manifest.indicatorCode,
554			freq: manifest.freq
555		};
556	}
557	
558	let publishQueue: Promise<unknown> = Promise.resolve();
559	
560	export function publishUpload(uploadId: string): Promise<PublishUploadResult> {
561		const next = publishQueue.then(
562			() => publishUploadNow(uploadId),
563			() => publishUploadNow(uploadId)
564		);
565		publishQueue = next.catch(() => undefined);
566		return next;
567	}

