 1	import { env } from '$env/dynamic/private';
 2	import { dev } from '$app/environment';
 3	import type { Handle } from '@sveltejs/kit';
 4	import { existsSync, copyFileSync, mkdirSync } from 'fs';
 5	import { join, resolve } from 'path';
 6	
 7	function unauthorized() {
 8		return new Response('Authentication required', {
 9			status: 401,
10			headers: {
11				'WWW-Authenticate': 'Basic realm="Colombia en Datos Admin"'
12			}
13		});
14	}
15	
16	function isAdminAuthorized(request: Request): boolean {
17		const username = env.ADMIN_USERNAME || (dev ? 'admin' : undefined);
18		const password = env.ADMIN_PASSWORD || env.ADMIN_TOKEN || (dev ? 'admin' : undefined);
19	
20		if (!username || !password) return false;
21	
22		const authorization = request.headers.get('authorization');
23		if (!authorization?.startsWith('Basic ')) return false;
24	
25		const credentials = atob(authorization.slice('Basic '.length));
26		const separator = credentials.indexOf(':');
27		if (separator === -1) return false;
28	
29		const providedUsername = credentials.slice(0, separator);
30		const providedPassword = credentials.slice(separator + 1);
31	
32		return providedUsername === username && providedPassword === password;
33	}
34	
35	function requiresAdminAuth(pathname: string, method: string): boolean {
36		return (
37			pathname.startsWith('/admin') ||
38			pathname.startsWith('/api/admin') ||
39			((pathname === '/api/indicators' || pathname === '/api/indicators/') && method !== 'GET')
40		);
41	}
42	
43	function bootstrapCanonicalDb() {
44		const dataPath = process.env.DATA_PATH;
45		if (!dataPath) return;
46	
47		const targetDir = resolve(dataPath);
48		const target = join(targetDir, 'observations.duckdb');
49		if (existsSync(target)) return;
50	
51		const template = join(process.cwd(), 'data', 'observations.duckdb.template');
52		if (!existsSync(template)) return;
53	
54		mkdirSync(targetDir, { recursive: true });
55		console.log('[bootstrap] Seeding canonical DB from template:', template, '→', target);
56		copyFileSync(template, target);
57	}
58	
59	export const handle: Handle = async ({ event, resolve }) => {
60		bootstrapCanonicalDb();
61	
62		if (
63			requiresAdminAuth(event.url.pathname, event.request.method) &&
64			!isAdminAuthorized(event.request)
65		) {
66			return unauthorized();
67		}
68	
69		return resolve(event);
70	};
