  1	import { json } from '@sveltejs/kit';
  2	import { and, eq, inArray } from 'drizzle-orm';
  3	import { getAvailableIndicators } from '$lib/server/duckdb';
  4	import { getDb } from '$lib/db/client';
  5	import {
  6		dataSources,
  7		dimensionDefinitions,
  8		indicatorDimensions,
  9		indicatorFrequencies,
 10		indicatorGroups,
 11		indicators
 12	} from '$lib/db/schema';
 13	import type { RequestHandler } from './$types';
 14	
 15	const CODE_PATTERN = /^[A-Za-z0-9_][A-Za-z0-9_.-]*$/;
 16	const FREQ_PATTERN = /^[A-Z]$/;
 17	
 18	interface NormalizedCreateIndicatorPayload {
 19		code: string;
 20		name: string;
 21		dataSourceCode: string;
 22		dataSourceName: string;
 23		groupCode: string;
 24		groupName: string;
 25		dimensionsByFreq: Record<string, string[]>;
 26		shortName: string | null;
 27		description: string | null;
 28		methodology: string | null;
 29		sourceCitation: string | null;
 30		unit: string | null;
 31		unitMult: number | null;
 32		decimals: number | null;
 33		defaultViz: string | null;
 34		updated: string | null;
 35	}
 36	
 37	function isRecord(value: unknown): value is Record<string, unknown> {
 38		return typeof value === 'object' && value !== null && !Array.isArray(value);
 39	}
 40	
 41	function stringValue(value: unknown): string | null {
 42		return typeof value === 'string' && value.trim().length > 0 ? value.trim() : null;
 43	}
 44	
 45	function integerValue(value: unknown): number | null {
 46		if (value === null || value === undefined || value === '') return null;
 47		if (typeof value === 'number' && Number.isInteger(value)) return value;
 48		if (typeof value !== 'string') return null;
 49	
 50		const parsed = Number.parseInt(value, 10);
 51		return Number.isFinite(parsed) && String(parsed) === value.trim() ? parsed : null;
 52	}
 53	
 54	function humanizeCode(code: string): string {
 55		return code
 56			.replace(/[_.-]+/g, ' ')
 57			.replace(/\s+/g, ' ')
 58			.trim()
 59			.replace(/\b\w/g, (letter) => letter.toUpperCase());
 60	}
 61	
 62	function normalizePayload(
 63		body: unknown
 64	): { ok: true; value: NormalizedCreateIndicatorPayload } | { ok: false; errors: string[] } {
 65		const errors: string[] = [];
 66	
 67		if (!isRecord(body)) {
 68			return { ok: false, errors: ['Request body must be a JSON object'] };
 69		}
 70	
 71		const code = stringValue(body.code);
 72		const name = stringValue(body.name);
 73		const dataSourceCode = stringValue(body.dataSourceCode) || stringValue(body.areaCode);
 74		const groupCode = stringValue(body.groupCode);
 75	
 76		if (!code) errors.push('code is required');
 77		else if (!CODE_PATTERN.test(code))
 78			errors.push('code may only contain letters, numbers, _, . and -');
 79	
 80		if (!name) errors.push('name is required');
 81		if (!dataSourceCode) errors.push('dataSourceCode is required');
 82		else if (!CODE_PATTERN.test(dataSourceCode)) {
 83			errors.push('dataSourceCode may only contain letters, numbers, _, . and -');
 84		}
 85	
 86		if (!groupCode) errors.push('groupCode is required');
 87		else if (!CODE_PATTERN.test(groupCode)) {
 88			errors.push('groupCode may only contain letters, numbers, _, . and -');
 89		}
 90	
 91		const dimensionsByFreqInput = body.dimensionsByFreq;
 92		const dimensionsByFreq: Record<string, string[]> = {};
 93	
 94		if (!isRecord(dimensionsByFreqInput)) {
 95			errors.push('dimensionsByFreq must be an object like { "A": ["GEO_LEVEL"] }');
 96		} else {
 97			for (const [rawFreq, rawDimensions] of Object.entries(dimensionsByFreqInput)) {
 98				const freq = rawFreq.trim().toUpperCase();
 99	
100				if (!FREQ_PATTERN.test(freq)) {
101					errors.push(`Invalid frequency "${rawFreq}"; expected a single letter like A, M or Q`);
102					continue;
103				}
104	
105				if (!Array.isArray(rawDimensions)) {
106					errors.push(`dimensionsByFreq.${rawFreq} must be an array of dimension codes`);
107					continue;
108				}
109	
110				const normalizedDimensions: string[] = [];
111				for (const rawDimension of rawDimensions) {
112					const dimension = stringValue(rawDimension)?.toUpperCase();
113					if (!dimension) {
114						errors.push(`dimensionsByFreq.${rawFreq} contains an invalid dimension code`);
115						continue;
116					}
117					if (!CODE_PATTERN.test(dimension)) {
118						errors.push(`Invalid dimension code "${dimension}"`);
119						continue;
120					}
121					if (!normalizedDimensions.includes(dimension)) normalizedDimensions.push(dimension);
122				}
123	
124				dimensionsByFreq[freq] = normalizedDimensions;
125			}
126		}
127	
128		if (isRecord(dimensionsByFreqInput) && Object.keys(dimensionsByFreq).length === 0) {
129			errors.push('dimensionsByFreq must include at least one frequency');
130		}
131	
132		const unitMult = integerValue(body.unitMult);
133		if (
134			body.unitMult !== undefined &&
135			body.unitMult !== null &&
136			body.unitMult !== '' &&
137			unitMult === null
138		) {
139			errors.push('unitMult must be an integer');
140		}
141	
142		const decimals = integerValue(body.decimals);
143		if (
144			body.decimals !== undefined &&
145			body.decimals !== null &&
146			body.decimals !== '' &&
147			decimals === null
148		) {
149			errors.push('decimals must be an integer');
150		}
151	
152		if (errors.length > 0 || !code || !name || !dataSourceCode || !groupCode) {
153			return { ok: false, errors };
154		}
155	
156		return {
157			ok: true,
158			value: {
159				code,
160				name,
161				dataSourceCode,
162				dataSourceName:
163					stringValue(body.dataSourceName) || stringValue(body.areaName) || humanizeCode(dataSourceCode),
164				groupCode,
165				groupName: stringValue(body.groupName) || humanizeCode(groupCode),
166				dimensionsByFreq,
167				shortName: stringValue(body.shortName),
168				description: stringValue(body.description),
169				methodology: stringValue(body.methodology),
170				sourceCitation: stringValue(body.sourceCitation) || stringValue(body.source),
171				unit: stringValue(body.unit),
172				unitMult,
173				decimals,
174				defaultViz: stringValue(body.defaultViz),
175				updated: stringValue(body.updated)
176			}
177		};
178	}
179	
180	function isUniqueConstraintError(error: unknown): boolean {
181		return error instanceof Error && /unique|constraint/i.test(error.message);
182	}
183	
184	export const GET: RequestHandler = async () => {
185		const indicators = await getAvailableIndicators();
186		return json({ indicators });
187	};
188	
189	export const POST: RequestHandler = async ({ request }) => {
190		let body: unknown;
191	
192		try {
193			body = await request.json();
194		} catch {
195			return json({ error: 'Invalid JSON body' }, { status: 400 });
196		}
197	
198		const normalized = normalizePayload(body);
199		if (!normalized.ok) {
200			return json({ error: 'Validation failed', errors: normalized.errors }, { status: 400 });
201		}
202	
203		const payload = normalized.value;
204		const db = getDb();
205	
206		const existingIndicator = await db
207			.select({ id: indicators.id })
208			.from(indicators)
209			.where(eq(indicators.code, payload.code))
210			.limit(1);
211	
212		if (existingIndicator.length > 0) {
213			return json(
214				{ error: `Indicator ${payload.code} already exists`, code: payload.code },
215				{ status: 409 }
216			);
217		}
218	
219		const requestedDimensionCodes = [...new Set(Object.values(payload.dimensionsByFreq).flat())];
220	
221		if (requestedDimensionCodes.length > 0) {
222			const knownDimensions = await db
223				.select({ code: dimensionDefinitions.code })
224				.from(dimensionDefinitions)
225				.where(inArray(dimensionDefinitions.code, requestedDimensionCodes));
226	
227			const knownDimensionCodes = new Set(knownDimensions.map((dimension) => dimension.code));
228			const missingDimensionCodes = requestedDimensionCodes.filter(
229				(code) => !knownDimensionCodes.has(code)
230			);
231	
232			if (missingDimensionCodes.length > 0) {
233				return json(
234					{
235						error: 'Unknown dimension codes',
236						dimensions: missingDimensionCodes
237					},
238					{ status: 400 }
239				);
240			}
241		}
242	
243		try {
244			const created = await db.transaction(async (tx) => {
245				const existingDataSource = await tx
246					.select({ id: dataSources.id })
247					.from(dataSources)
248					.where(eq(dataSources.code, payload.dataSourceCode))
249					.limit(1);
250	
251				const dataSourceId =
252					existingDataSource[0]?.id ??
253					(
254						await tx
255							.insert(dataSources)
256							.values({ code: payload.dataSourceCode, name: payload.dataSourceName })
257							.returning({ id: dataSources.id })
258					)[0].id;
259	
260				const existingGroup = await tx
261					.select({ id: indicatorGroups.id })
262					.from(indicatorGroups)
263					.where(
264						and(
265							eq(indicatorGroups.dataSourceId, dataSourceId),
266							eq(indicatorGroups.code, payload.groupCode)
267						)
268					)
269					.limit(1);
