416	export async function getAvailableFrequenciesByIndicator(
417		indicatorCodes?: string[]
418	): Promise<Map<string, string[]>> {
419		if (indicatorCodes && indicatorCodes.length === 0) return new Map();
420	
421		try {
422			const conditions: string[] = [];
423			const params: string[] = [];
424	
425			if (indicatorCodes) {
426				conditions.push(`indicator_code IN (${indicatorCodes.map(() => '?').join(', ')})`);
427				params.push(...indicatorCodes);
428			}
429	
430			const rows = await runCanonicalQuery<{ indicator_code: string; freq: string }>(
431				`
432					SELECT DISTINCT indicator_code, freq
433					FROM observations
434					${conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : ''}
435					ORDER BY indicator_code, freq
436				`,
437				...params
438			);
439	
440			const frequencies = new Map<string, string[]>();
441			for (const row of rows) {
442				const current = frequencies.get(row.indicator_code) || [];
443				if (!current.includes(row.freq)) current.push(row.freq);
444				frequencies.set(row.indicator_code, current);
445			}
446	
447			return frequencies;
448		} catch (error) {
449			console.warn('[DuckDB] Could not load available frequencies from canonical store:', error);
450			return new Map();
451		}
452	}
