516				dataSource: dataSources.name
517			})
518			.from(indicators)
519			.innerJoin(indicatorGroups, eq(indicators.indicatorGroupId, indicatorGroups.id))
520			.innerJoin(dataSources, eq(indicatorGroups.dataSourceId, dataSources.id));
521	
522		const frequencyMap = await getPublishedFrequenciesByIndicator(
523			rows.map((indicator) => indicator.code)
524		);
525	
526		return rows
527			.map((i) => {
528				const availableFrequencies = frequencyMap.get(i.code) || [];
529				return {
530					code: i.code,
531					name: i.name,
532					shortName: i.shortName,
533					frequency: availableFrequencies[0] || null,
534					availableFrequencies,
535					dataSource: i.dataSource || 'Unknown',
536					group: i.group || 'Unknown'
537				};
538			})
539			.filter((indicator) => indicator.availableFrequencies.length > 0);
540	}

