256							.values({ code: payload.dataSourceCode, name: payload.dataSourceName })
257							.returning({ id: dataSources.id })
258					)[0].id;
259	
260				const existingGroup = await tx
261					.select({ id: indicatorGroups.id })
262					.from(indicatorGroups)
263					.where(
264						and(
265							eq(indicatorGroups.dataSourceId, dataSourceId),
266							eq(indicatorGroups.code, payload.groupCode)
267						)
268					)
269					.limit(1);
270	
271				const groupId =
272					existingGroup[0]?.id ??
273					(
274						await tx
275							.insert(indicatorGroups)
276							.values({
277								dataSourceId,
278								code: payload.groupCode,
279								name: payload.groupName,
280								sourceType: 'api'
281							})
282							.returning({ id: indicatorGroups.id })
283					)[0].id;
284	
285				const [indicator] = await tx
286					.insert(indicators)
287					.values({
288						indicatorGroupId: groupId,
289						code: payload.code,
290						name: payload.name,
291						shortName: payload.shortName,
292						description: payload.description,
