 67				return fail(400, { error: 'El nombre es obligatorio' });
 68			}
 69	
 70			await db
 71				.update(indicators)
 72				.set({
 73					name,
 74					shortName: optionalString(formData.get('shortName')),
 75					description: optionalString(formData.get('description')),
 76					methodology: optionalString(formData.get('methodology')),
 77					sourceCitation: optionalString(formData.get('sourceCitation')),
 78					unit: optionalString(formData.get('unit')),
 79					unitMult: optionalInteger(formData.get('unitMult')),
 80					decimals: optionalInteger(formData.get('decimals')),
 81					defaultViz: optionalString(formData.get('defaultViz')),
 82					updated: optionalString(formData.get('updated')),
 83					updatedAt: sql`(CURRENT_TIMESTAMP)`
 84				})
 85				.where(eq(indicators.code, code));
 86	
 87			throw redirect(303, `/admin/indicators/${encodeURIComponent(code)}?saved=1`);
 88		}
 89	};
360		updated: string | null;
361		availableDimensions: string[];
362	}
363	
364	export async function getIndicatorMetadata(
365		indicatorCode: string,
366		freq: string = 'M',
367		_refArea: string = 'CO'
368	): Promise<IndicatorMetadata | null> {
369		console.log(`[DuckDB] Getting metadata for ${indicatorCode}, freq=${freq}`);
370	
371		const pgDb = getDb();
372		const indicatorRecord = await pgDb
373			.select()
374			.from(indicators)
375			.where(eq(indicators.code, indicatorCode))
376			.limit(1);
377	
378		if (indicatorRecord.length === 0) {
379			console.warn(`[DuckDB] Indicator ${indicatorCode} not found`);
380			return null;
381		}
382	
383		const indicator = indicatorRecord[0];
384	
385		const dims = await pgDb
386			.select({ code: indicatorDimensions.dimensionCode })
387			.from(indicatorDimensions)
388			.where(
389				and(
390					eq(indicatorDimensions.indicatorId, indicator.id),
391					or(eq(indicatorDimensions.freq, freq), eq(indicatorDimensions.freq, '*'))
392				)
393			);
394	
395		return {
396			code: indicator.code,
397			name: indicator.name,
398			shortName: indicator.shortName,
399			description: indicator.description,
400			methodology: indicator.methodology,
401			sourceCitation: indicator.sourceCitation,
402			frequency: indicator.frequency,
403			unit: indicator.unit,
404			unitMult: indicator.unitMult,
405			decimals: indicator.decimals,
406			defaultViz: indicator.defaultViz,
407			updated: indicator.updated,
408			availableDimensions: dims.map((d) => d.code)
409		};
410	}
411	
412	// ---------------------------------------------------------------------------
413	// Legacy helpers (kept for backward compatibility during transition)
414	// ---------------------------------------------------------------------------
415	
416	export async function getAvailableFrequenciesByIndicator(
417		indicatorCodes?: string[]
418	): Promise<Map<string, string[]>> {
419		if (indicatorCodes && indicatorCodes.length === 0) return new Map();
420	
421		try {
422			const conditions: string[] = [];
423			const params: string[] = [];
424	
425			if (indicatorCodes) {
426				conditions.push(`indicator_code IN (${indicatorCodes.map(() => '?').join(', ')})`);
427				params.push(...indicatorCodes);
428			}
429	
430			const rows = await runCanonicalQuery<{ indicator_code: string; freq: string }>(
431				`
432					SELECT DISTINCT indicator_code, freq
433					FROM observations
434					${conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : ''}
435					ORDER BY indicator_code, freq
436				`,
437				...params
438			);
439	
440			const frequencies = new Map<string, string[]>();
441			for (const row of rows) {
442				const current = frequencies.get(row.indicator_code) || [];
443				if (!current.includes(row.freq)) current.push(row.freq);
444				frequencies.set(row.indicator_code, current);
445			}
446	
447			return frequencies;
448		} catch (error) {
449			console.warn('[DuckDB] Could not load available frequencies from canonical store:', error);
450			return new Map();
451		}
452	}
453	
454	export async function getPublishedFrequenciesByIndicator(
455		indicatorCodes?: string[]
456	): Promise<Map<string, string[]>> {
457		if (indicatorCodes && indicatorCodes.length === 0) return new Map();
458	
459		const pgDb = getDb();
460		const metadataRows = await pgDb
461			.select({
462				indicatorCode: indicators.code,
463				freq: indicatorDataSources.freq
464			})
465			.from(indicatorDataSources)
466			.innerJoin(indicators, eq(indicatorDataSources.indicatorId, indicators.id))
467			.innerJoin(dataReleases, eq(indicatorDataSources.releaseId, dataReleases.id))
468			.where(
469				and(
470					eq(dataReleases.status, 'published'),
471					indicatorCodes ? inArray(indicators.code, indicatorCodes) : undefined
472				)
473			);
474	
475		if (metadataRows.length === 0) return new Map();
476	
477		const metadataPairs = new Set(
478			metadataRows.map((row) => `${row.indicatorCode}\u0000${row.freq}`)
479		);
480		const observedFrequencies = await getAvailableFrequenciesByIndicator(
481			[...new Set(metadataRows.map((row) => row.indicatorCode))]
482		);
483		const result = new Map<string, string[]>();
484	
485		for (const [indicatorCode, frequencies] of observedFrequencies.entries()) {
486			for (const freq of frequencies) {
487				if (!metadataPairs.has(`${indicatorCode}\u0000${freq}`)) continue;
488				const current = result.get(indicatorCode) || [];
489				if (!current.includes(freq)) current.push(freq);
490				result.set(indicatorCode, current);
491			}
492		}
493	
494		return result;
495	}
496	
497	export async function getAvailableIndicators(): Promise<
498		Array<{
499			code: string;
500			name: string;
501			shortName: string | null;
502			frequency: string | null;
503			availableFrequencies: string[];
504			dataSource: string;
505			group: string;
506		}>
507	> {
508		const pgDb = getDb();
509		const rows = await pgDb
510			.select({
511				code: indicators.code,
512				name: indicators.name,
513				shortName: indicators.shortName,
514				frequency: indicators.frequency,
515				group: indicatorGroups.name,
516				dataSource: dataSources.name
517			})
518			.from(indicators)
519			.innerJoin(indicatorGroups, eq(indicators.indicatorGroupId, indicatorGroups.id))
520			.innerJoin(dataSources, eq(indicatorGroups.dataSourceId, dataSources.id));
521	
522		const frequencyMap = await getPublishedFrequenciesByIndicator(
523			rows.map((indicator) => indicator.code)
524		);
525	
526		return rows
527			.map((i) => {
528				const availableFrequencies = frequencyMap.get(i.code) || [];
529				return {
530					code: i.code,
531					name: i.name,
532					shortName: i.shortName,
533					frequency: availableFrequencies[0] || null,
534					availableFrequencies,
535					dataSource: i.dataSource || 'Unknown',
536					group: i.group || 'Unknown'
537				};
538			})
539			.filter((indicator) => indicator.availableFrequencies.length > 0);
540	}

